+    /**
+     * Accepts written $this, self and named-class receivers; other identities stay unknown.
+     */
+    public function matches(Expr\PropertyFetch|Expr\NullsafePropertyFetch|Expr\StaticPropertyFetch $node, string $property, string $target): bool
+    {
+        if (!$node->name instanceof Node\Identifier && !$node->name instanceof Node\VarLikeIdentifier) {
+            return false;
+        }
+        if ($node->name->toString() !== $property) {
+            return false;
+        }
+        if ($node instanceof Expr\StaticPropertyFetch) {
+            return $node->class instanceof Node\Name && in_array(strtolower($node->class->toString()), ['self', strtolower(explode('::', $target)[0])], true);
+        }
